console.log("GO360 script cargado"); (function () { document.addEventListener("DOMContentLoaded", function () { const btn = document.querySelector(".top-bar__hamburger"); const menu = document.querySelector(".mobile-menu"); if (btn && menu) { btn.addEventListener("click", () => { menu.style.display = menu.style.display === "block" ? "none" : "block"; }); } const profileBtn = document.querySelector(".top-bar__profile-link"); const profileMenu = document.querySelector(".top-bar__profile-menu"); if (profileBtn && profileMenu) { profileBtn.addEventListener("click", (e) => { e.stopPropagation(); profileMenu.classList.toggle("visible"); }); document.addEventListener("click", () => { profileMenu.classList.remove("visible"); }); profileMenu.addEventListener("click", (e) => { e.stopPropagation(); }); } }); })();